CREATE DATABASE IF NOT EXISTS terminal_dex;
CREATE TABLE IF NOT EXISTS terminal_dex.instructions (chain LowCardinality(String), event_date Date, block_time Nullable(DateTime64(3, 'UTC')), slot UInt64, signature String, instruction_index UInt16, inner_index Int32, event_id String, program_id String, protocol Nullable(String), registry_version UInt32, decoder_version Nullable(UInt32), parsed_type Nullable(String), accounts Array(String), data Nullable(String), raw_payload_hash FixedString(64), payload String) ENGINE = ReplacingMergeTree ORDER BY (chain, event_date, program_id, slot, signature, instruction_index, inner_index);
CREATE TABLE IF NOT EXISTS terminal_dex.swaps (chain LowCardinality(String), event_date Date, block_time DateTime64(3, 'UTC'), slot UInt64, signature String, event_index UInt16, swap_id String, pool String, protocol LowCardinality(String), base_mint String, quote_mint String, input_mint String, output_mint String, input_amount_raw UInt256, output_amount_raw UInt256, trade_fee_raw UInt256, commitment LowCardinality(String), decoder_version UInt32, raw_payload_hash FixedString(64), payload String) ENGINE = ReplacingMergeTree ORDER BY (chain, event_date, pool, slot, signature, event_index);
CREATE TABLE IF NOT EXISTS terminal_dex.balance_changes (chain LowCardinality(String), event_date Date, block_time Nullable(DateTime64(3, 'UTC')), slot UInt64, signature String, token_account String, owner Nullable(String), mint String, decimals UInt8, pre_amount_raw UInt256, post_amount_raw UInt256, closed Bool) ENGINE = ReplacingMergeTree ORDER BY (chain, event_date, mint, token_account, slot, signature);
CREATE TABLE IF NOT EXISTS terminal_dex.dead_letters (chain LowCardinality(String), observed_at DateTime64(3, 'UTC'), source String, identity String, payload_hash Nullable(FixedString(64)), error String, attempts UInt32, payload String) ENGINE = ReplacingMergeTree ORDER BY (chain, toDate(observed_at), source, identity);
CREATE TABLE IF NOT EXISTS terminal_dex.canonical_events (chain LowCardinality(String), sequence UInt64, event_type LowCardinality(String), slot UInt64, block_time Nullable(DateTime64(3, 'UTC')), commitment LowCardinality(String), blockhash String, payload String) ENGINE = ReplacingMergeTree(sequence) ORDER BY (chain, sequence);
CREATE TABLE IF NOT EXISTS terminal_dex.canonical_instructions (chain LowCardinality(String), slot UInt64, block_time Nullable(DateTime64(3, 'UTC')), signature String, commitment LowCardinality(String), event_id String, instruction_index UInt16, inner_index Nullable(UInt16), program_id String, protocol Nullable(String), registry_version UInt32, decoder_version Nullable(UInt32), parsed_type Nullable(String), accounts Array(String), data Nullable(String), raw_payload_hash FixedString(64), payload String) ENGINE = MergeTree ORDER BY (chain, slot, signature, instruction_index, ifNull(inner_index, 65535));
CREATE TABLE IF NOT EXISTS terminal_dex.canonical_swaps (chain LowCardinality(String), slot UInt64, block_time Nullable(DateTime64(3, 'UTC')), signature String, commitment LowCardinality(String), swap_id String, event_index UInt16, pool String, protocol LowCardinality(String), base_mint String, quote_mint String, input_mint String, output_mint String, input_amount_raw UInt256, output_amount_raw UInt256, trade_fee_raw Nullable(UInt256), decoder_version Nullable(UInt32), raw_payload_hash FixedString(64), payload String) ENGINE = MergeTree ORDER BY (chain, slot, signature, event_index);
CREATE TABLE IF NOT EXISTS terminal_dex.canonical_balance_changes (chain LowCardinality(String), slot UInt64, block_time Nullable(DateTime64(3, 'UTC')), signature String, commitment LowCardinality(String), account_index UInt16, token_account String, owner Nullable(String), program_id Nullable(String), mint String, decimals UInt8, pre_amount_raw UInt256, post_amount_raw UInt256, closed Bool, payload String) ENGINE = MergeTree ORDER BY (chain, slot, signature, account_index);
CREATE TABLE IF NOT EXISTS terminal_dex.canonical_native_transfers (chain LowCardinality(String), slot UInt64, block_time Nullable(DateTime64(3, 'UTC')), signature String, commitment LowCardinality(String), transfer_id String, instruction_index UInt16, inner_index Nullable(UInt16), program_id String, transfer_kind LowCardinality(String), source String, destination String, lamports_raw UInt64, allocated_space_raw Nullable(UInt64), owner_program Nullable(String), base_address Nullable(String), seed Nullable(String), decoder_version UInt32, raw_payload_hash FixedString(64), payload String) ENGINE = MergeTree ORDER BY (chain, slot, signature, instruction_index, ifNull(inner_index, 65535));
ALTER TABLE terminal_dex.canonical_native_transfers ADD COLUMN IF NOT EXISTS transfer_kind LowCardinality(String) DEFAULT 'transfer' AFTER program_id;
ALTER TABLE terminal_dex.canonical_native_transfers ADD COLUMN IF NOT EXISTS allocated_space_raw Nullable(UInt64) AFTER lamports_raw;
ALTER TABLE terminal_dex.canonical_native_transfers ADD COLUMN IF NOT EXISTS owner_program Nullable(String) AFTER allocated_space_raw;
ALTER TABLE terminal_dex.canonical_native_transfers ADD COLUMN IF NOT EXISTS base_address Nullable(String) AFTER owner_program;
ALTER TABLE terminal_dex.canonical_native_transfers ADD COLUMN IF NOT EXISTS seed Nullable(String) AFTER base_address;
CREATE TABLE IF NOT EXISTS terminal_dex.canonical_dead_letters (chain LowCardinality(String), observed_at DateTime64(3, 'UTC'), source String, identity String, payload_hash Nullable(FixedString(64)), error String, attempts UInt32, resolved Bool, resolution Nullable(String), payload String) ENGINE = MergeTree ORDER BY (chain, source, identity);
CREATE TABLE IF NOT EXISTS terminal_dex.canonical_candles (schema_version UInt16, source_sequence UInt64, chain LowCardinality(String), pool String, interval_seconds UInt32, bucket_start DateTime64(3, 'UTC'), base_mint String, quote_mint String, base_decimals Nullable(UInt8), quote_decimals Nullable(UInt8), open_numerator_raw UInt256, open_denominator_raw UInt256, high_numerator_raw UInt256, high_denominator_raw UInt256, low_numerator_raw UInt256, low_denominator_raw UInt256, close_numerator_raw UInt256, close_denominator_raw UInt256, base_volume_raw UInt256, quote_volume_raw UInt256, trades UInt64, first_slot UInt64, last_slot UInt64, commitment LowCardinality(String)) ENGINE = MergeTree ORDER BY (chain, pool, interval_seconds, bucket_start);
